export async function recordRti(wallet: WalletClient, reader: PublicClient, p: { commitment: Hex; dueMs: number; nowMs?: number; commission?: string }) {
  const head = await reader.getBlockNumber();
  const dueBlock = head + BigInt(Math.ceil((p.dueMs - (p.nowMs ?? Date.now())) / 1000 / BLOCK_SECONDS));
  if (dueBlock <= head + 30n) throw new Error("the reply deadline has passed, so there is nothing left to time");
  const payload: RtiPayload = { v: 2, commitment: p.commitment.toLowerCase(), due_block: dueBlock.toString() };
  const r = await sealedBatch(
    wallet,
    reader,
    [
      { payload: jsonToPayload(payload), contentType: JSON_T, attributes: rtiAttrs(p.commitment), expires: ExpirationTime.atBlock(rtiExpiryBlock(dueBlock)), flags: { readonly: true, permissionlessExtension: false } },
      // The opt-in public count rides in the same batch, sealed the same way, and lives as long as the record.
      ...(p.commission ? [{ payload: new Uint8Array(), contentType: BIN, attributes: rtiTallyAttrs(p.commission, dueBlock), expires: ExpirationTime.atBlock(rtiExpiryBlock(dueBlock)), flags: { readonly: true, permissionlessExtension: false } }] : []),
    ],
    new Set(),
    rtiSealOwner(p.commitment),
  );
  return { key: r.createdEntities[0], txHash: r.txHash, dueBlock };
}

export async function rtiTally(client: PublicClient, commission: string): Promise<RtiTally> {
  const head = await client.getBlockNumber();
  const base = [eq("project", str(PROJECT)), eq("type", str(RTI_TALLY)), eq("ic", str(commission))];
  const fields = { key: true, owner: true, creator: true, creationFlags: true } as const;
  const sealedOnly = (rows: Row[]) => rows.filter((r) => r.creationFlags.readonly && !same(r.owner, r.creator)).length;
  const [all, late] = await Promise.all([
    fetchAll(client.select(fields).where(...base).limit(200) as unknown as Pageable, { atBlock: head, max: 5000 }),
    fetchAll(client.select(fields).where(...base, lt("due_block", u64(head))).limit(200) as unknown as Pageable, { atBlock: head, max: 5000 }),
  ]);
  return { commission, head, recorded: sealedOnly(all.rows), overdue: sealedOnly(late.rows) };
}

export function rtiCommitment(salt: Hex, fileHash: Hex): Hex {
  return bytesToHex(sha256(concat(utf8("proof-of-life/rti/v1"), hexToBytes(salt), hexToBytes(fileHash)))) as Hex;
}

